/* IMAGEN */
.project-card img {
    object-fit: contain;
    background: #111;
}

.card-body {
    display: flex;
    flex-direction: column;
    gap: 8px;
}

.cert-list {
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-top: 10px;
}

.cert-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #111827;
    padding: 12px 14px;
    border-radius: 8px;
}

.cert-item h3 {
    font-size: 1rem;
    margin-bottom: 2px;
}

.cert-item p {
    font-size: 1.20rem;
    color: #9ca3af;
}

/* Botón chico */
.btn-cert {
    background: #3b82f6;
    color: #ffffff;
    padding: 6px 12px;
    font-size: 0.8rem;
    border-radius: 6px;
    text-decoration: none;
    transition: 0.2s;
    white-space: nowrap;
    font-size: 1.5rem;
}

.btn-cert:hover {
    background: #2563eb;
    transform: translateY(-1px);
}

/* ===== EDUCACION - SECCION COMPLETA EN PANTALLA ===== */
#educacion {
    padding: 20px 30px;
    min-height: 100vh; 
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 15px;
}

#educacion h1 {
    font-size: 1.8rem; 
    margin-bottom: 12px;
}

#educacion .edu-intro {
    font-size: 1rem;
    max-width: 600px;
    line-height: 1.4;
    color: #cbd5e1;
}

#educacion .timeline {
    border-left: 2px solid #3b82f6;
    padding-left: 15px;
    margin-top: 0; 
    display: flex;
    flex-direction: column;
    gap: 5px;
}

#educacion .timeline-item {
    margin-bottom: 12px;
    padding: 10px 12px;
    border-radius: 8px;
}

#educacion .timeline-item.highlight {
    border: 1px solid #3b82f6;
    box-shadow: 0 0 12px rgba(59,130,246,0.15);
}

#educacion .timeline-date {
    font-size: 1rem;
    color: #9ca3af;
    margin-bottom: 2px;
}

#educacion .timeline-content h3 {
    font-size: 1rem;
    margin-bottom: 2px;
}

#educacion .timeline-content p {
    font-size: 0.85rem;
    line-height: 1.3;
}

/* CERTIFICADOS */
#educacion .cert-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 8px;
}

#educacion .cert-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #111827;
    padding: 8px 10px;
    border-radius: 6px;
}

#educacion .cert-item h3 {
    font-size: 0.9rem;
    margin-bottom: 2px;
}

#educacion .cert-item p {
    font-size: 0.75rem;
    color: #9ca3af;
}

#educacion .btn-cert {
    padding: 4px 8px;
    font-size: 0.7rem;
}


.edu-intro {
    margin-top: 15px;
    margin-bottom: 40px;
    font-size: 1.05rem;
    color: #cbd5e1;
    max-width: 750px;
}

/* Timeline más visual */
.timeline {
    border-left: 3px solid #3b82f6;
    padding-left: 25px;
    display: flex;
    flex-direction: column;
    gap: 25px;
}

.timeline-item {
    background: #1f2937;
    padding: 18px 20px;
    border-radius: 10px;
    transition: 0.25s;
}

.timeline-item:hover {
    transform: translateX(6px);
    background: #374151;
}

.timeline-item.highlight {
    border: 1px solid #3b82f6;
    box-shadow: 0 0 20px rgba(59,130,246,0.15);
}

.timeline-date {
    font-size: 0.85rem;
    color: #9ca3af;
    margin-bottom: 6px;
}

.timeline-content h3 {
    font-size: 1.2rem;
    margin-bottom: 6px;
}

.timeline-content p {
    font-size: 0.95rem;
}

/* ===== MODAL ===== */
.modal {
    display: none;
    position: fixed;
    z-index: 999;
    left: 0;
    top: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.85);
    justify-content: center;
    align-items: center;
    padding: 20px; /* margen para que no toque los bordes */
}

/* ===== CONTENIDO ===== */
.modal-content {
    background: #1e1e1e;
    padding: 20px;
    border-radius: 12px;
    width: 90%;              /* ocupa hasta 90% del ancho de la pantalla */
    max-width: 400px;         /* ancho máximo fijo */
    max-height: 60vh;         /* altura máxima 90% de la ventana */
    overflow: hidden;         /* evita scroll externo */
    text-align: center;
    color: white;
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
}

/* ===== IMAGEN ===== */
.modal-content img {
    max-width: 100%;          /* nunca se pasa del ancho del modal */
    max-height: 50vh;         /* ocupa como máximo la mitad de la pantalla */
    height: auto;
    border-radius: 8px;
    margin-bottom: 15px;
    object-fit: contain;      /* escala sin cortar */
}

/* ===== BOTON CERRAR ===== */
.close {
    position: absolute;
    right: 15px;
    top: 10px;
    font-size: 28px;
    font-weight: bold;
    cursor: pointer;
    color: #fff;
}

/* ===== LINKS DEL MODAL ===== */
#modalLinks {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-top: 20px;
    width: 100%;
}

#modalLinks a {
    background: #3b82f6;
    padding: 10px 16px;
    border-radius: 6px;
    color: white;
    text-decoration: none;
    font-size: 1rem;
    font-weight: 500;
    transition: 0.2s;
    text-align: center;
}

#modalLinks a:hover {
    background: #2563eb;
}

/* ===== RESET ===== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
    scroll-snap-type: y mandatory;
    height: 100%;
    font-size: 14px; /* reducido para que la letra entre en pantalla */
}

body {
    display: flex;
    flex-direction: column;
    font-family: "Inter", system-ui, sans-serif;
    background: #0f172a;
    color: #e5e7eb;
    margin-bottom: 120px;
    min-height: 100vh;
    height: 100%;
    font-size: 0.9rem;
    margin: 0;
}

main.content {
    flex: 1;
    display: flex;
    flex-direction: column;
}

/* ===== SIDEBAR ===== */
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    width: 300px;
    height: 100vh;
    background: #111827;
    border-right: 1px solid #1f2937;
    padding: 30px 20px;
}

.profile {
    text-align: center;
    margin-bottom: 40px;
}

.photo {
    width: 180px;
    height: 180px;
    border-radius: 50%;
    border: 3px solid #3b82f6;
    margin-bottom: 15px;
}

.profile h4 {
    font-size: 1rem;
    font-weight: 600;
}

/* ===== MENU ===== */
.menu {
    list-style: none;
}

.menu a {
    display: block;
    padding: 12px 16px;
    margin-bottom: 10px;
    border-radius: 8px;
    color: #9ca3af;
    text-decoration: none;
    font-weight: 500;
    font-size: 0.85rem;
    transition: all 0.2s;
}

.menu a:hover {
    background: #1f2937;
    color: #fff;
}

.menu a.active {
    background: #3b82f6;
    color: white;
}

/* ===== CONTENT ===== */
.content {
    margin-left: 300px;
    padding: 60px 80px;
    max-width: 1200px;
    min-height: 100vh;
}

.section {
    margin-bottom: 120px;
    padding: 40px;
    min-height: 100vh;
    scroll-snap-align: start;
}

.section h1 {
    font-size: 2rem; /* reducido para adaptarse */
    margin-bottom: 20px;
}

.section p {
    color: #9ca3af;
    max-width: 750px;
    line-height: 1.6;
    font-size: 0.9rem;
}

/* ===== BUTTON ===== */
.btn-download {
    display: inline-block;
    margin-top: 25px;
    padding: 10px 18px;
    background: #3b82f6;
    border-radius: 8px;
    color: white;
    text-decoration: none;
    font-size: 0.85rem;
    transition: 0.25s;
}

.btn-download:hover {
    transform: translateY(-2px);
    background: #2563eb;
}

/* ===== PROJECTS ===== */
.projects-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 24px;
    margin-top: 25px;
}

.project-card {
    background: #1f2937;
    border-radius: 12px;
    overflow: hidden;
    transition: 0.3s;
    cursor: pointer;
}

.project-card:hover {
    transform: translateY(-6px);
    box-shadow: 0 15px 30px rgba(0,0,0,0.4);
}

.project-card img {
    width: 100%;
    height: 160px;
    object-fit: cover;
}

.card-body {
    padding: 16px;
}

.card-body h3 {
    margin-bottom: 6px;
    font-size: 1rem;
}

.card-body p {
    font-size: 0.85rem;
}

.card-body a {
    color: #3b82f6;
    font-size: 0.85rem;
    text-decoration: none;
}

/* ===== TIMELINE ===== */
.timeline {
    border-left: 2px solid #3b82f6;
    margin-top: 25px;
    padding-left: 18px;
}

.timeline-item {
    margin-bottom: 20px;
}

.timeline-date {
    color: #9ca3af;
    font-size: 0.85rem;
}

.timeline-content h3 {
    font-size: 1.1rem;
}

.timeline-content p {
    font-size: 0.85rem;
}

/* ===== SKILLS ===== */
.skills-wrapper {
    margin-top: 35px;
    max-width: 850px;
}

.skill-group {
    margin-bottom: 35px;
}

.skill-group h2 {
    font-size: 1.3rem;
    margin-bottom: 12px;
    color: #e5e7eb;
    border-left: 4px solid #3b82f6;
    padding-left: 8px;
}

.skills-grid {
    display: flex;
    flex-wrap: wrap;
    gap: 10px;
}

.skill {
    background: #1f2937;
    padding: 10px 16px;
    border-radius: 999px;
    font-size: 0.9rem;
    font-weight: 500;
    transition: 0.2s ease;
}

.skill:hover {
    background: #3b82f6;
    transform: translateY(-2px);
}

/* ===== CONTACT ===== */
.contact-list {
    margin-top: 30px;
    display: flex;
    flex-direction: column;
    gap: 15px;
}

.contact-item {
    display: flex;
    align-items: center;
    gap: 15px;
    background: #1f2937;
    padding: 14px;
    border-radius: 10px;
    text-decoration: none;
    color: white;
    transition: 0.2s;
    max-width: 400px;
    font-size: 0.9rem;
}

.contact-item:hover {
    transform: translateX(5px);
    background: #374151;
}

.contact-item img {
    width: 24px;
}

.inicio-contacto {
    margin-top: 120px;
}

.contactus {
    margin-top: 250px;
}

// Selecciona todos los links del menú y las secciones
const menuLinks = document.querySelectorAll(".menu a");
const sections = document.querySelectorAll(".section");

// Función para actualizar el link activo
function updateActiveMenu() {
    let scrollPos = window.scrollY + window.innerHeight / 2; // punto medio de la pantalla

    sections.forEach(section => {
        const top = section.offsetTop;
        const bottom = top + section.offsetHeight;
        const id = section.getAttribute("id");

        const link = document.querySelector(`.menu a[href="#${id}"]`);

        if (scrollPos >= top && scrollPos < bottom) {
            link.classList.add("active");
        } else {
            link.classList.remove("active");
        }
    });
}

// Llama a la función al hacer scroll y al cargar
window.addEventListener("scroll", updateActiveMenu);
window.addEventListener("load", updateActiveMenu);


function showSection(id) {

    const sections = document.querySelectorAll(".section");

    sections.forEach(section => {
        section.classList.remove("active");
    });

    document.getElementById(id).classList.add("active");
}

const cards = document.querySelectorAll(".project-card");
const modal = document.getElementById("projectModal");

cards.forEach(card => {

    card.addEventListener("click", () => {

        const img = card.dataset.img;
        const title = card.dataset.title;
        const text = card.dataset.text;

        // 👉 Obtener TODOS los links dentro de la card
        const links = card.querySelectorAll("a");

        openModal(img, title, text, links);

    });

});

function openModal(img, title, text, links) {

    document.getElementById("modalImg").src = img;
    document.getElementById("modalTitle").textContent = title;
    document.getElementById("modalText").textContent = text;

    const linksContainer = document.getElementById("modalLinks");
    linksContainer.innerHTML = "";

    links.forEach(link => {
        const newLink = document.createElement("a");
        newLink.href = link.href;
        newLink.textContent = link.textContent;
        newLink.target = "_blank";

        linksContainer.appendChild(newLink);
    });

    modal.style.display = "flex";
}

function closeModal() {
    modal.style.display = "none";
}

window.addEventListener("click", (e) => {
    if (e.target === modal) closeModal();
});
